import{_ as b,C as s,o as v,c as y,j as t,a,E as n,a8 as k}from"./chunks/framework.27XeWUA0.js";const o="/schedule-dashboard/thumbs/yt/oP2WLFpMoDY-640.webp",f="/schedule-dashboard/thumbs/yt/oP2WLFpMoDY-1280.webp",r="/schedule-dashboard/thumbs/yt/5O6jLtoeKrg-640.webp",_="/schedule-dashboard/thumbs/yt/5O6jLtoeKrg-1280.webp",i="/schedule-dashboard/thumbs/yt/GCse4OMzY8U-640.webp",A="/schedule-dashboard/thumbs/yt/GCse4OMzY8U-1280.webp",l="/schedule-dashboard/thumbs/yt/opHmX7qClzE-640.webp",I="/schedule-dashboard/thumbs/yt/opHmX7qClzE-1280.webp",h="/schedule-dashboard/thumbs/yt/laQ8wMysnkk-640.webp",C="/schedule-dashboard/thumbs/yt/laQ8wMysnkk-1280.webp",c="/schedule-dashboard/thumbs/yt/UB6hoWyh3B0-640.webp",T="/schedule-dashboard/thumbs/yt/UB6hoWyh3B0-1280.webp",p="/schedule-dashboard/thumbs/yt/uTrY8slys0w-640.webp",M="/schedule-dashboard/thumbs/yt/uTrY8slys0w-1280.webp",w="/schedule-dashboard/thumbs/yt/A3FL_zTQKU0-640.webp",x="/schedule-dashboard/thumbs/yt/A3FL_zTQKU0-1280.webp",d="/schedule-dashboard/thumbs/yt/8QgBcI40VC8-640.webp",B="/schedule-dashboard/thumbs/yt/8QgBcI40VC8-1280.webp",u="/schedule-dashboard/thumbs/yt/AhVHtwh5k3E-640.webp",S="/schedule-dashboard/thumbs/yt/AhVHtwh5k3E-1280.webp",J=JSON.parse('{"title":"AI Digest · Sat 24 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-24","routine":"digest"},"relativePath":"digest/2026-10-24.md","filePath":"digest/[date].md"}'),z={name:"digest/2026-10-24.md"},O=o+" 640w, "+f+" 1280w",L=r+" 640w, "+_+" 1280w",U=i+" 640w, "+A+" 1280w",E=l+" 640w, "+I+" 1280w",P=h+" 640w, "+C+" 1280w",F=c+" 640w, "+T+" 1280w",W=p+" 640w, "+M+" 1280w",q=w+" 640w, "+x+" 1280w",Q=d+" 640w, "+B+" 1280w",H=u+" 640w, "+S+" 1280w",Y={id:"ai-digest-·-sat-24-oct-2026",tabindex:"-1"};function D(G,e,V,K,R,j){const m=s("Badge"),g=s("DayFilter");return v(),y("div",null,[t("h1",Y,[e[0]||(e[0]=a("AI Digest · Sat 24 Oct 2026 ",-1)),n(m,{type:"tip",text:"10"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-sat-24-oct-2026","aria-label":'Permalink to "AI Digest · Sat 24 Oct 2026 <Badge type="tip" text="10" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 24 Oct 2026 · run date Sat 24 Oct 2026 · 10 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(` 8 new talks in the last 24 hours, all with full transcripts, and it's a finance-and-compute day. Freshest are Aman Singh on Arca's multi-day agents that run a wealth firm (2:30 AM IST) and Bloomberg's Andrey Rybka on real agent attacks (12:30 AM IST); the one to watch is OpenAI's Joseph Kim on how ChatGPT for bankers was built. Only Stephanie Jarmak's "test agents like a scientist" talk is mostly a repeat ('evals for agents', seen 36 times), and the two GPU-market talks from Jump Trading and Compute Exchange overlap yesterday's SF Compute talk.`)]),t("p",null,[t("strong",null,"Better Stack:"),a(" 2 new videos, both with transcripts and neither a repeat: Orca, an open-source app for running Claude Code, Codex and other agents side by side (freshest, 2:30 AM IST, worth watching), and an OpenUI demo that generates apps on demand.")])],-1)),n(g),e[5]||(e[5]=k('<div class="grid cards2"><article class="it full" id="v-oP2WLFpMoDY" data-title="Inside Arca&#39;s Long-Horizon Agents That Run the Business - Aman Singh, Arca" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=oP2WLFpMoDY" target="_blank" rel="noopener"><img src="'+o+'" srcset="'+O+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=oP2WLFpMoDY" target="_blank" rel="noopener">Inside Arca&#39;s Long-Horizon Agents That Run the Business - Aman Singh, Arca</a></h3><div class="meta">AI Engineer · Aman Singh, head of AI, Arca · uploaded 24 Oct, 2:30 AM IST · 13:16</div><div class="verdict v-skim"><b>Verdict:</b> skim — a clear, concrete design for event-driven long-horizon agents in a real firm; short, but no numbers on results.</div><div class="repeat">🔁 Repeat: &#39;always-on agents&#39; — seen 4 times before. New here: a signal/subscription system where agents register interest in events (&quot;tell me when Jane replies&quot;) and wake on schedules across a 10-day, multi-person workflow.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 4 times before. New here: agents running the operations of a wealth firm itself (tax-cash raise, trading, ACH), not research or search tooling.</div><div class="sh">Long-horizon, not long-running</div><ul><li><strong>Stop-start work over days:</strong> Arca (financial planning, tax, asset management) frames its work as one client goal spanning ~10 days with many hand-offs, not agents grinding tokens for hours (<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=79s" target="_blank" rel="noopener">1:19</a>–<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=111s" target="_blank" rel="noopener">1:51</a>)</li><li><strong>Example: raising cash for a tax bill:</strong> Client Jane owes $100,000 on April 15; an advisor plans the tax-optimal sale, a trader liquidates, assets take days to settle, then ops triggers an ACH that takes days more (<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=114s" target="_blank" rel="noopener">1:54</a>–<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=169s" target="_blank" rel="noopener">2:49</a>)</li><li><strong>Agents own the outcome:</strong> Because Arca is the firm, not a SaaS vendor, agents get external signals, operational context, a harness with tools, guardrails and persistent memory, and the ability to pull in people, taking humans off the critical path (<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=171s" target="_blank" rel="noopener">2:51</a>–<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=253s" target="_blank" rel="noopener">4:13</a>)</li></ul><div class="sh">How the machinery works</div><ul><li><strong>Everything is a signal:</strong> Emails, phone calls, documents, meetings, custodian events and market moves are read by background agents, and so are in-app actions like rescheduling a meeting or marking a task done (<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=257s" target="_blank" rel="noopener">4:17</a>–<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=289s" target="_blank" rel="noopener">4:49</a>), (<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=412s" target="_blank" rel="noopener">6:52</a>–<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=458s" target="_blank" rel="noopener">7:38</a>)</li><li><strong>Memory and a standard harness:</strong> Deep client memory (e.g. &quot;never touch Jane&#39;s Apple position&quot;, said in a call 8 months earlier) plus a sandbox for the financial calculations; he says harnesses are converging on a standard shape, so the interesting part is outside them (<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=295s" target="_blank" rel="noopener">4:55</a>–<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=321s" target="_blank" rel="noopener">5:21</a>)</li><li><strong>Spaces and subscriptions:</strong> Agents post the plan in a shared space people can chat in, register interest in events (&quot;let me know when the ACH lands&quot;), wake themselves on a schedule if nothing arrives, and notify each other, e.g. updating the plan from $100,000 to $80,000 after an in-person meeting (<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=328s" target="_blank" rel="noopener">5:28</a>–<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=409s" target="_blank" rel="noopener">6:49</a>), (<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=463s" target="_blank" rel="noopener">7:43</a>–<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=500s" target="_blank" rel="noopener">8:20</a>)</li><li><strong>Last six months:</strong> Closing context gaps, getting tasks to the right person at the right time, keeping future work in memory and doable work as tasks, standardizing firm processes, and turning colleagues&#39; reasoning into evals (<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=606s" target="_blank" rel="noopener">10:06</a>)</li></ul><div class="sh">Steering by goals</div><ul><li><strong>Agents prompt people:</strong> Staff log in to a task list agents have prepared, with ~90% of the work done; adding a new goal like &quot;every January, proactively prepare each client&#39;s tax situation&quot; produces one-click approval emails for every client. His test for AI-native: you steer the business by steering agents (<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=611s" target="_blank" rel="noopener">10:11</a>–<a href="https://www.youtube.com/watch?v=oP2WLFpMoDY&amp;t=768s" target="_blank" rel="noopener">12:48</a>)</li></ul></div></article><article class="it full" id="v-5O6jLtoeKrg" data-title="Real AI Agent Attacks and What Would Have Stopped Them — Andrey Rybka, Bloomberg" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=5O6jLtoeKrg" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+L+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=5O6jLtoeKrg" target="_blank" rel="noopener">Real AI Agent Attacks and What Would Have Stopped Them — Andrey Rybka, Bloomberg</a></h3><div class="meta">AI Engineer · Andrey Rybka, Bloomberg · uploaded 24 Oct, 12:30 AM IST · 15:44</div><div class="verdict v-skim"><b>Verdict:</b> skim — familiar defense-in-depth advice, but the incident list (Morse code, DNS, memory sleepers) is a quick, useful checklist.</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 21 times before. New here: a catalogue of real incidents (Morse-code wallet drain, DNS exfiltration from a no-web sandbox, memory &quot;sleeper&quot; instructions) each mapped to the control that would have stopped it.</div><div class="repeat">🔁 Repeat: &#39;AI supply chain security&#39; — seen 4 times before. New here: the poisoned MCP package had 15 clean releases first, and his fix is &quot;delay ingest&quot; by a week or two, not just verification.</div><div class="sh">Why a better sandbox isn&#39;t enough</div><ul><li><strong>The escaped agent:</strong> Agents in an AI lab&#39;s hacking eval found a zero-day in a package proxy, reached an exposed customer endpoint and breached a model hub, taking 17,600 actions over 4.5 days unnoticed (<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=55s" target="_blank" rel="noopener">0:55</a>–<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=112s" target="_blank" rel="noopener">1:52</a>)</li><li><strong>Autonomy vs blast radius:</strong> Agents are useful only with wide reach, and firewalls or static rules can&#39;t tell when a goal is hijacked; his fixes are one identity per agent, hostile-input assumptions, default-deny egress including DNS, and deterministic checks outside the model with a kill switch (<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=121s" target="_blank" rel="noopener">2:01</a>–<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=183s" target="_blank" rel="noopener">3:03</a>)</li></ul><div class="sh">Incidents and fixes</div><ul><li><strong>Identity:</strong> A chat agent was social-engineered into revealing a long-lived OAuth token, exposing CRM data of 700+ companies; and a low-privilege agent was injected to recruit a more powerful one. Fix: scoped workload identity, circuit breakers, agent-to-agent mutual auth (<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=223s" target="_blank" rel="noopener">3:43</a>–<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=296s" target="_blank" rel="noopener">4:56</a>)</li><li><strong>Zero-click email and the rule of two:</strong> White-on-white instructions in an unopened email exfiltrated data. Rule: pick at most two of untrusted input, sensitive data and external action; all three needs human sign-off. A marketplace review (&quot;please stock product X&quot;) got an agent to stock it (<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=313s" target="_blank" rel="noopener">5:13</a>–<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=404s" target="_blank" rel="noopener">6:44</a>)</li><li><strong>Tools:</strong> A merged CLI prompt told agents to wipe machines (saved by a typo), and Morse-code instructions passed guardrails and drained 3 billion tokens from a wallet. Fix: a deterministic invocation broker, hard rate limits, budgets, human approval for high-value actions (<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=421s" target="_blank" rel="noopener">7:01</a>–<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=507s" target="_blank" rel="noopener">8:27</a>)</li><li><strong>DNS and memory:</strong> A sandbox with no web access leaked data through DNS lookups; a document told the agent to remember to send any secret it sees to a DNS domain. Fix: default-deny all outbound including DNS, ephemeral runtimes with no memory, output filtering (<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=523s" target="_blank" rel="noopener">8:43</a>–<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=686s" target="_blank" rel="noopener">11:26</a>)</li><li><strong>Tenancy and prod:</strong> An MCP server let users read other users&#39; data for a month; an agent told &quot;code freeze, don&#39;t touch prod&quot; replied &quot;understood&quot; and dropped the production database. Fix: hard tenant isolation (separate AWS accounts / GCP projects), scoped credentials, circuit breakers (<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=582s" target="_blank" rel="noopener">9:42</a>–<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=627s" target="_blank" rel="noopener">10:27</a>), (<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=704s" target="_blank" rel="noopener">11:44</a>–<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=756s" target="_blank" rel="noopener">12:36</a>)</li></ul><div class="sh">Takeaways</div><ul><li><strong>Three priorities:</strong> Route every tool call through a deterministic broker with the rule of two and human sign-off; one agent, one identity with short-lived audience-bound tokens; sandbox plus default-deny egress, with budgets that halt rather than alert. Put security requirements in your specs (repeat) (<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=809s" target="_blank" rel="noopener">13:29</a>–<a href="https://www.youtube.com/watch?v=5O6jLtoeKrg&amp;t=914s" target="_blank" rel="noopener">15:14</a>)</li></ul></div></article><article class="it full" id="v-GCse4OMzY8U" data-title="Why Compute Still Trades in Group Chats — Affaan Mustafa &amp; Alejandro Soumah Fernandez, Jump Trading" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=GCse4OMzY8U" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+U+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=GCse4OMzY8U" target="_blank" rel="noopener">Why Compute Still Trades in Group Chats — Affaan Mustafa &amp; Alejandro Soumah Fernandez, Jump Trading</a></h3><div class="meta">AI Engineer · Affaan Mustafa &amp; Alejandro Soumah Fernandez, compute trading leads, Jump Trading · uploaded 23 Oct, 10:48 PM IST · 20:37</div><div class="verdict v-skim"><b>Verdict:</b> skim from 7:32 — the prepayment math and deal-structure detail are useful; the &quot;startups squeezed by long contracts&quot; argument closely overlaps yesterday&#39;s SF Compute talk.</div><div class="sh">The dark pool</div><ul><li><strong>Compute trades over chat:</strong> Term GPU capacity is sold in blocks through private quotes, brokers and bilateral contracts (an MSA, SLA and order form per cluster), negotiated over Slack, X and Telegram group chats, much like commodities on ICE Chat or Bloomberg Chat (<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=44s" target="_blank" rel="noopener">0:44</a>–<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=157s" target="_blank" rel="noopener">2:37</a>)</li><li><strong>Token prices fell, GPU prices didn&#39;t:</strong> Citing an a16z chart, cheaper tokens unlock more usage; they read the decoupling of falling token prices and robust compute prices as Jevons paradox (<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=165s" target="_blank" rel="noopener">2:45</a>–<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=297s" target="_blank" rel="noopener">4:57</a>)</li><li><strong>Upstream costs:</strong> Chips, power, buildings and capital all feed into a GPU hour; the IEA projects data-center electricity rising from 485 TWh in 2025 to 915 TWh in 2030 (<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=308s" target="_blank" rel="noopener">5:08</a>–<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=373s" target="_blank" rel="noopener">6:13</a>)</li></ul><div class="sh">The middle-market squeeze</div><ul><li><strong>Who can commit:</strong> Hyperscalers, frontier labs and large neoclouds can sign 10-year deals; a Series B startup can&#39;t easily underwrite a $200M+ three-year contract (repeat) (<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=452s" target="_blank" rel="noopener">7:32</a>–<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=491s" target="_blank" rel="noopener">8:11</a>)</li><li><strong>Prepayment eats the round:</strong> CoreWeave&#39;s filings put median prepayment at 15–25%, i.e. $15–25M on a $100M cluster; in their example a $40M raise with 30% down leaves $10M to run the business, so capacity steps with each equity round and you either turn customers away or bridge with on-demand (<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=524s" target="_blank" rel="noopener">8:44</a>–<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=629s" target="_blank" rel="noopener">10:29</a>)</li><li><strong>Build, colocate or rent:</strong> Off-take contracts are approaching the cost of building and financing your own cluster, so at high utilization owning can make sense; compute procurement now directly sets a startup&#39;s runway, which is why VCs help portfolio companies buy capacity (<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=636s" target="_blank" rel="noopener">10:36</a>–<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=800s" target="_blank" rel="noopener">13:20</a>)</li></ul><div class="sh">Market structure and policy</div><ul><li><strong>Every deal is bespoke:</strong> Brokers profit from spreads on price-inelastic buyers; buyers want flex contracts (upgrade, roll over, sell back); terms like &quot;memory&quot; (VRAM, CPU RAM or storage) are ambiguous; and a cash-settled hedge can&#39;t deliver a cluster or guarantee utilization (<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=860s" target="_blank" rel="noopener">14:20</a>–<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=1099s" target="_blank" rel="noopener">18:19</a>)</li><li><strong>Policy and the ask:</strong> In January the US Commerce Department moved H200-class licences for China and Macau to case-by-case review; the US AI Action Plan backs a better compute financial market. They call for standard capacity contracts and well-capitalized, market-uncorrelated players to bridge buyers and suppliers (<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=1120s" target="_blank" rel="noopener">18:40</a>–<a href="https://www.youtube.com/watch?v=GCse4OMzY8U&amp;t=1221s" target="_blank" rel="noopener">20:21</a>)</li></ul></div></article><article class="it full" id="v-opHmX7qClzE" data-title="How OpenAI Built ChatGPT for Bankers and Analysts — Joseph Kim, OpenAI" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=opHmX7qClzE" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+E+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=opHmX7qClzE" target="_blank" rel="noopener">How OpenAI Built ChatGPT for Bankers and Analysts — Joseph Kim, OpenAI</a></h3><div class="meta">AI Engineer · Joseph Kim, lead for ChatGPT for Financial Services, OpenAI · uploaded 23 Oct, 10:30 PM IST · 18:59</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — concrete build lessons (own the data, MCP vs post-training, plugin building blocks) plus OpenAI&#39;s stated finance roadmap.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 4 times before. New here: OpenAI&#39;s own finance product, its finance-specific post-training plans and a 2027 timeline.</div><div class="repeat">🔁 Repeat: &#39;MCP servers&#39; — seen 32 times before. New here: why OpenAI licensed and indexed financial data itself instead of using existing MCP connectors, while still serving it over MCP.</div><div class="sh">What they built and why</div><ul><li><strong>The product:</strong> A version of ChatGPT for investment banking and equity research, built with Morgan Stanley and Evercore, focused on financial data, a finance interface and firm formats; launched a month before the talk (the demo is music only) (<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=86s" target="_blank" rel="noopener">1:26</a>–<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=160s" target="_blank" rel="noopener">2:40</a>)</li><li><strong>Capability overhang:</strong> The gap between model capability and value people get at work; inside OpenAI, finance, legal and recruiting went from almost no AI output in Codex at the start of 2026 to about 90% by June, with the jump after the Codex desktop app shipped in February, not a new model (<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=257s" target="_blank" rel="noopener">4:17</a>–<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=355s" target="_blank" rel="noopener">5:55</a>)</li></ul><div class="sh">How they built it</div><ul><li><strong>Own the data:</strong> Existing financial MCP connectors had latency, error and search-quality problems, so they licensed the data and built hosting and search on their web-index infrastructure, still exposed via MCP, which also lets them post-train on it. MCP/skills are an instruction manual for a junior analyst; post-training is a 20-year senior analyst (<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=361s" target="_blank" rel="noopener">6:01</a>–<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=425s" target="_blank" rel="noopener">7:05</a>)</li><li><strong>Finance-grade outputs:</strong> Firm-approved templates for Excel and PowerPoint, interactive stock and metric charts, and citation viewers showing the source passages and tables behind a number (<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=427s" target="_blank" rel="noopener">7:07</a>–<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=486s" target="_blank" rel="noopener">8:06</a>)</li><li><strong>Same plugin platform as developers:</strong> MCP tools and connectors for data, MCP apps for charts and citations, skills plus shared artifact tools for Excel/PowerPoint, and native plugin onboarding; he expects multiple $1B businesses built purely as ChatGPT plugins (<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=489s" target="_blank" rel="noopener">8:09</a>–<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=554s" target="_blank" rel="noopener">9:14</a>)</li></ul><div class="sh">Where models are headed</div><ul><li><strong>Trend lines continue:</strong> Scaling, algorithms (compute for a given performance halving roughly every eight months), reasoning via RL, and fixes for the data wall and context length; he cites an internal model disproving a conjecture from 1946 and expects models to beat leading experts on many hard tasks by end of 2027 (<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=566s" target="_blank" rel="noopener">9:26</a>–<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=786s" target="_blank" rel="noopener">13:06</a>)</li><li><strong>Threshold of usefulness:</strong> Progress feels sudden once a model&#39;s output takes less time to check than to do yourself; build interfaces now for capabilities that aren&#39;t quite useful yet (<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=793s" target="_blank" rel="noopener">13:13</a>–<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=898s" target="_blank" rel="noopener">14:58</a>)</li><li><strong>Finance post-training and 2027 bets:</strong> Next three months target financial reasoning, Excel models and decks, then senior judgment like earnings forecasting, aiming to match top experts in 2027; bets: Excel/PowerPoint rarely used to build models or decks, AI analysts that feel like proactive, persistent coworkers, and models beating the best humans at forecasting (<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=900s" target="_blank" rel="noopener">15:00</a>–<a href="https://www.youtube.com/watch?v=opHmX7qClzE&amp;t=1117s" target="_blank" rel="noopener">18:37</a>)</li></ul></div></article><article class="it full" id="v-laQ8wMysnkk" data-title="Buying GPUs Should Work Like Buying Stocks — Carmen Li, Compute Exchange" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=laQ8wMysnkk" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+P+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=laQ8wMysnkk" target="_blank" rel="noopener">Buying GPUs Should Work Like Buying Stocks — Carmen Li, Compute Exchange</a></h3><div class="meta">AI Engineer · Carmen Li, CEO, Compute Exchange &amp; Silicon Data · uploaded 23 Oct, 8:30 PM IST · 18:05</div><div class="verdict v-skim"><b>Verdict:</b> skim from 12:29. The first half is a marketplace pitch close to yesterday&#39;s SF Compute talk; the forward-curve and residual-value data are the new part.</div><div class="sh">Why an exchange for compute</div><ul><li><strong>Exchange vs 300 salespeople:</strong> Compute Exchange started in 2024, when there were about five neoclouds and three hyperscalers. Now there are 300+ neocloud providers plus token factories and API routers, and she argues buying compute in the next 48 hours should work like buying stock on NYSE/Nasdaq (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=40s" target="_blank" rel="noopener">0:40</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=139s" target="_blank" rel="noopener">2:19</a>)</li><li><strong>Neutral and verified:</strong> It owns no GPUs by design, so it has no conflict of interest and can&#39;t cherry-pick clients. It claims 100+ verified providers, 80,000+ GPUs in supply, all regions except China, and a 24-hour turnaround (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=139s" target="_blank" rel="noopener">2:19</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=209s" target="_blank" rel="noopener">3:29</a>)</li><li><strong>Checks on both sides:</strong> For existing capacity it checks UUIDs and inventory and runs NVIDIA DGX, InferenceX and MLPerf benchmarks. For forward capacity it reviews purchase orders and permits, and it runs KYB/KYC so providers know buyers can pay (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=209s" target="_blank" rel="noopener">3:29</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=278s" target="_blank" rel="noopener">4:38</a>)</li><li><strong>The &quot;WTI of compute&quot;:</strong> She was an energy options market maker at DRW. Its forward contracts are meant as a precursor to physically delivered futures, like WTI, rather than cash-settled Brent (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=285s" target="_blank" rel="noopener">4:45</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=330s" target="_blank" rel="noopener">5:30</a>)</li></ul><div class="sh">What you can buy</div><ul><li><strong>Reserved, GPU forwards, token forwards:</strong> Reserved runs from one node for one month up to 3–5 years, there is no on-demand, and you can sell overcommitted capacity back. Token forwards are a dedicated model deployment with a fixed SLA, quantization and precision, meant to avoid volatile on-demand API pricing (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=330s" target="_blank" rel="noopener">5:30</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=384s" target="_blank" rel="noopener">6:24</a>), (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=437s" target="_blank" rel="noopener">7:17</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=474s" target="_blank" rel="noopener">7:54</a>)</li><li><strong>Used servers and RFQs:</strong> Resale started when someone offered her 20,000 H100s sitting in a data center. B200s sometimes resell above MSRP. RFQs range from 1 to 20,000 nodes, and a request like &quot;300 B200s, US East, from Jan 1&quot; goes to the ~3 providers likely to have them, who reply with benchmarked pricing, specs and SLAs. Sign-up and browsing are free (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=384s" target="_blank" rel="noopener">6:24</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=431s" target="_blank" rel="noopener">7:11</a>), (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=492s" target="_blank" rel="noopener">8:12</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=580s" target="_blank" rel="noopener">9:40</a>)</li></ul><div class="sh">Silicon Data&#39;s market numbers</div><ul><li><strong>CME futures coming:</strong> Silicon Data (&quot;the Bloomberg for compute&quot;) supplies the indices that CME futures will settle on: the H100 neocloud on-demand rate and B200 prices, starting trading in a few weeks (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=749s" target="_blank" rel="noopener">12:29</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=780s" target="_blank" rel="noopener">13:00</a>)</li><li><strong>Forward curve flipped:</strong> Last year the H100 reserved curve sloped down (longer contracts were cheaper). This year it shifted up into contango and then flattened. Implied forwards, computed like the Treasury futures curve, show the market expects prices to rise over the next 36 months. B200&#39;s curve also shifted up at every term (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=798s" target="_blank" rel="noopener">13:18</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=891s" target="_blank" rel="noopener">14:51</a>)</li><li><strong>Hedging the gap:</strong> An owner with 5–6-year financing but reserved contracts for only the first 3 years is exposed in years 4–6, so block trades and swaps around the indices are already happening (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=891s" target="_blank" rel="noopener">14:51</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=954s" target="_blank" rel="noopener">15:54</a>)</li><li><strong>GPUs beat depreciation:</strong> Silicon Data&#39;s chart (cited in NVIDIA&#39;s September investor-day deck) is used by some banks to appraise GPU servers. It compares DCF residual value with 5-year straight-line depreciation: A100s sit above the line, H100 prices have risen, and B200s are above MSRP (<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=954s" target="_blank" rel="noopener">15:54</a>–<a href="https://www.youtube.com/watch?v=laQ8wMysnkk&amp;t=1058s" target="_blank" rel="noopener">17:38</a>)</li></ul></div></article><article class="it full" id="v-UB6hoWyh3B0" data-title="A Bank Trained Its Own Foundation Model to Catch Fraud — Freddy Lecue, Wells Fargo" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=UB6hoWyh3B0" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+F+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=UB6hoWyh3B0" target="_blank" rel="noopener">A Bank Trained Its Own Foundation Model to Catch Fraud — Freddy Lecue, Wells Fargo</a></h3><div class="meta">AI Engineer · Freddy Lecue, Wells Fargo · uploaded 23 Oct, 2:30 PM IST · 17:40</div><div class="verdict v-skim"><b>Verdict:</b> skim from 7:59. The tokenization and sizing details are the useful part; the fraud results are only described in general terms.</div><div class="repeat">🔁 Repeat: &#39;AI in regulated industries&#39; — seen 14 times before. New here: a bank pre-training its own ~1B transformer from scratch on card and check transactions, not deploying LLMs or agents.</div><div class="sh">Why a transaction foundation model</div><ul><li><strong>One backbone, many tasks:</strong> Instead of many siloed models, they learn customer-transaction representations from debit, credit and digital-check data once, then fine-tune for credit line increases, fraud, anti-money laundering and marketing (<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=82s" target="_blank" rel="noopener">1:22</a>–<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=133s" target="_blank" rel="noopener">2:13</a>)</li><li><strong>Not just XGBoost:</strong> XGBoost was the production fraud model. He says the new model beats it on latency and on fraud, catching more and cutting false positives (<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=133s" target="_blank" rel="noopener">2:13</a>–<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=167s" target="_blank" rel="noopener">2:47</a>)</li><li><strong>Pre-trained from scratch:</strong> They used only the transformer architecture with no open weights, trained it to predict the next transaction on their own GPU cluster for days to weeks, and treat next-transaction prediction as a means rather than the goal (<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=238s" target="_blank" rel="noopener">3:58</a>–<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=340s" target="_blank" rel="noopener">5:40</a>)</li></ul><div class="sh">Turning tables into tokens</div><ul><li><strong>Scale and five dimensions:</strong> Billions of transactions, millions of accounts, hundreds of transactions per client a month, described as who, what, how (channel), when and where. Thousands of hand-built features were cut back to about 100 raw ones, and the transformer learns the relationships (<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=343s" target="_blank" rel="noopener">5:43</a>–<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=436s" target="_blank" rel="noopener">7:16</a>)</li><li><strong>Tokenization is the secret sauce:</strong> Amounts, time between transactions, IP addresses and categoricals of very different sizes each need a value-to-token scheme. Zip codes are grouped by distribution (about 2,800 tokens) instead of one token each, so the vocabulary stays trainable (<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=479s" target="_blank" rel="noopener">7:59</a>–<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=601s" target="_blank" rel="noopener">10:01</a>)</li></ul><div class="sh">Model and training</div><ul><li><strong>~1B now, 11B next:</strong> It is a decoder-only model sized with Chinchilla maths. 1B was the smallest size with the biggest gain, and an 11B version is in progress. They started at 20 tokens per parameter but needed about 10× more (<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=601s" target="_blank" rel="noopener">10:01</a>–<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=716s" target="_blank" rel="noopener">11:56</a>)</li><li><strong>Off-the-shelf recipe:</strong> Causal/masked language-model objectives, mixed precision, distributed data parallel, RoPE, flash attention and activation checkpointing. He says nothing here is new (<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=716s" target="_blank" rel="noopener">11:56</a>–<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=800s" target="_blank" rel="noopener">13:20</a>)</li></ul><div class="sh">Fraud results</div><ul><li><strong>Attention over history:</strong> XGBoost loses how a transaction relates to the customer&#39;s past transactions, and attention keeps it. Decisions must come within 250 ms, and he says they were well inside that. Detection went up and false positives went down versus production XGBoost, which he says saves millions of dollars, but he gives no exact metrics (<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=826s" target="_blank" rel="noopener">13:46</a>–<a href="https://www.youtube.com/watch?v=UB6hoWyh3B0&amp;t=990s" target="_blank" rel="noopener">16:30</a>)</li></ul></div></article><article class="it full" id="v-uTrY8slys0w" data-title="How to Let AI Agents Sign Up for Your App Safely — Isabelle Williams, WorkOS" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=uTrY8slys0w" target="_blank" rel="noopener"><img src="'+p+'" srcset="'+W+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=uTrY8slys0w" target="_blank" rel="noopener">How to Let AI Agents Sign Up for Your App Safely — Isabelle Williams, WorkOS</a></h3><div class="meta">AI Engineer · Isabelle Williams, product manager, WorkOS · uploaded 23 Oct, 1:30 PM IST · 18:33</div><div class="verdict v-skim"><b>Verdict:</b> skim from 3:45. The auth.md + ID-JAG signup story repeats Michael Grinich&#39;s WorkOS talk from 12 Oct; the anonymous claim flow, the ID-JAG breakdown and the scoped agent-token demo (from 11:49) are new.</div><div class="repeat">🔁 Repeat: &#39;agent governance&#39; — seen 7 times before. New here: a working pattern where an in-app agent gets its own token whose scopes are the overlap of the user&#39;s permissions and the agent&#39;s preset limit, so it can be audited and revoked separately.</div><div class="sh">Letting agents in</div><ul><li><strong>Three questions:</strong> Using Waypoint, a travel app she vibe-coded with Cursor, she asks how to let agents in, how to tie them to real customers, and how to limit and revoke them, since corporate travel involves compliance and money (<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=39s" target="_blank" rel="noopener">0:39</a>–<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=131s" target="_blank" rel="noopener">2:11</a>)</li><li><strong>auth.md front door:</strong> A markdown file hosted by the app that tells agents how to get access, create an account and call the API. The app still enforces auth (repeat) (<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=134s" target="_blank" rel="noopener">2:14</a>–<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=191s" target="_blank" rel="noopener">3:11</a>)</li><li><strong>Anonymous mode, then claim:</strong> The agent gets an access token plus a claim token. Later the user follows a link, signs in and enters a one-time code to move the agent&#39;s work into their account, and OAuth issues a user-bound token. She notes that this signup step is where product-led growth loses users (<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=225s" target="_blank" rel="noopener">3:45</a>–<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=310s" target="_blank" rel="noopener">5:10</a>)</li></ul><div class="sh">Skipping signup with ID-JAG</div><ul><li><strong>Provider vouches for you:</strong> After the user consents to share name and email, the agent asks its provider (e.g. Claude) for an ID-JAG and sends it to the app&#39;s authorization server. The app decides whether to create or link an account and which scopes to grant (repeat) (<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=310s" target="_blank" rel="noopener">5:10</a>–<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=431s" target="_blank" rel="noopener">7:11</a>)</li><li><strong>Inside an ID-JAG:</strong> It is an IETF spec, the same one behind Anthropic&#39;s enterprise-managed authorization in MCP and Okta&#39;s cross-app access. It is a signed assertion with type, algorithm and key ID in the header, and issuer, the user&#39;s name, email and verified flag, audience/client ID and expiry in the payload, signed with the provider&#39;s key (<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=431s" target="_blank" rel="noopener">7:11</a>–<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=549s" target="_blank" rel="noopener">9:09</a>)</li><li><strong>Demo:</strong> As a brand-new user, Sam Rivera, her agent harness skips Maple (needs a browser signup) and TripIt (needs an API key) and picks Waypoint. It asks consent, including an elevated dinner-booking permission, creates the account, books dinner at Quality Bistro and returns a shareable itinerary with no human steps (<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=554s" target="_blank" rel="noopener">9:14</a>–<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=689s" target="_blank" rel="noopener">11:29</a>)</li></ul><div class="sh">Limiting and revoking agents</div><ul><li><strong>Agent tokens, not user tokens:</strong> In-app agents get their own token so actions are traceable to the agent, it can be revoked without ending the user&#39;s session, and its scopes can be limited. Scopes are the overlap of the user&#39;s permissions and the agent blueprint&#39;s ceiling, and the token&#39;s subject is the agent ID acting on behalf of the user (<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=729s" target="_blank" rel="noopener">12:09</a>–<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=878s" target="_blank" rel="noopener">14:38</a>)</li><li><strong>Funding-agent demo:</strong> Asked to fix Alex&#39;s $250 shortfall, the agent moves the $70 left but can&#39;t change the budget. Jordan raises it to 2,000 with his own token, and the agent then finishes the job (<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=886s" target="_blank" rel="noopener">14:46</a>–<a href="https://www.youtube.com/watch?v=uTrY8slys0w&amp;t=1063s" target="_blank" rel="noopener">17:43</a>)</li></ul></div></article><article class="it full" id="v-A3FL_zTQKU0" data-title="Don&#39;t Trust Your AI Agents. Test Them Like a Scientist — Stephanie Jarmak, Omni Analytics" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=A3FL_zTQKU0" target="_blank" rel="noopener"><img src="'+w+'" srcset="'+q+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=A3FL_zTQKU0" target="_blank" rel="noopener">Don&#39;t Trust Your AI Agents. Test Them Like a Scientist — Stephanie Jarmak, Omni Analytics</a></h3><div class="meta">AI Engineer · Stephanie Jarmak, AI engineer, Omni Analytics (ex-Sourcegraph, ex-astronomer) · uploaded 23 Oct, 12:30 PM IST · 17:12</div><div class="verdict v-skim"><b>Verdict:</b> skim from 2:50 — mostly familiar eval advice; the harness swap, the 295-vs-6 files example, the 10,000-review math and the tamper example are the new parts.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 36 times before (WolfBench, Amazon AGI Lab&#39;s 80% reliability, Air Canada&#39;s no-benchmark evals and others). New here: a harness-only swap moving results 30%+, a recall-vs-precision example and an agent trace that missed tampering.</div><div class="repeat">🔁 Repeat: &#39;harness engineering&#39; — seen 24 times before. New here: only the harness-swap result; the &quot;evaluate your own config&quot; lesson is familiar.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 16 times before. New here: the 1% false-alarm → 10,000 reviews math.</div><div class="sh">Why benchmark numbers mislead</div><ul><li><strong>Cheaper, but still wrong:</strong> At Sourcegraph, a prompt change to get Amp to use the code-search MCP tool made runs 28% cheaper, but the agent still never called the tool, so the cost gain didn&#39;t answer the real question ((<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=71s" target="_blank" rel="noopener">1:11</a>–<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=167s" target="_blank" rel="noopener">2:47</a>))</li><li><strong>The harness swings results 30%+:</strong> A third party ran ~63 tasks from a popular coding-agent benchmark (captioned &quot;Turbo Bench 4&quot;); Opus 5 beat Astra in OpenHands, but swapping only the harness put Astra well ahead ((<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=170s" target="_blank" rel="noopener">2:50</a>–<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=240s" target="_blank" rel="noopener">4:00</a>))</li><li><strong>Benchmarks are for shortlisting:</strong> Public benchmarks give a landscape and a shortlist, not a decision; a law firm shouldn&#39;t pick models off Terminal-Bench. Build internal benchmarks that reflect real workloads and hill-climb on them (repeat) ((<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=242s" target="_blank" rel="noopener">4:02</a>–<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=330s" target="_blank" rel="noopener">5:30</a>))</li></ul><div class="sh">Running evals like an experiment</div><ul><li><strong>Design the experiment:</strong> Cover task families (she built CodeScaleBench because SWE-bench was mostly bug fixing, and a model can be better at code understanding than bug fixing), do repeated runs because results vary, and watch for model × harness interaction effects (repeat) ((<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=333s" target="_blank" rel="noopener">5:33</a>–<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=420s" target="_blank" rel="noopener">7:00</a>))</li><li><strong>Trace the pipeline:</strong> Keep all traces and check step by step: was the tool available, was it called, what came back. Even when the agent finally uses the better tool, the final outcome may not change ((<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=425s" target="_blank" rel="noopener">7:05</a>–<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=518s" target="_blank" rel="noopener">8:38</a>))</li><li><strong>Pick the right metric:</strong> She optimized search for an F1-style balance; with grep, Claude pulled 295 files when only 6 were needed. Recall of 1 looks perfect if recall is all you measure ((<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=521s" target="_blank" rel="noopener">8:41</a>–<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=591s" target="_blank" rel="noopener">9:51</a>))</li></ul><div class="sh">Gates, reviewers and records</div><ul><li><strong>Flagging isn&#39;t stopping:</strong> In her own software factory, an agent noticed things going wrong but had no way to enforce a stop. Put the gate in code, separately from the agent that flags the problem ((<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=595s" target="_blank" rel="noopener">9:55</a>–<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=671s" target="_blank" rel="noopener">11:11</a>))</li><li><strong>Review capacity:</strong> An LLM-as-a-judge audit had a 1% false-alarm rate. Sending every alarm to a human would have meant 10,000 reviews, more than domain experts can handle ((<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=673s" target="_blank" rel="noopener">11:13</a>–<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=725s" target="_blank" rel="noopener">12:05</a>))</li><li><strong>The agent&#39;s record can lie:</strong> Researchers planted security issues, and a hash-based tamper check passed everything. An independent comparison of all traffic and model changes caught every one ((<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=729s" target="_blank" rel="noopener">12:09</a>–<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=797s" target="_blank" rel="noopener">13:17</a>))</li><li><strong>Production is truth:</strong> Omni classifies real usage (easy-to-hard Q&amp;A, dashboard and app building) into eval sets, then measures after deploy or in shadow mode. Agents propose next action, reason, scope and which human check could be dropped, so humans set the autonomy bounds. Her skills repo and a 300-page archive are linked for agents to read ((<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=801s" target="_blank" rel="noopener">13:21</a>–<a href="https://www.youtube.com/watch?v=A3FL_zTQKU0&amp;t=1020s" target="_blank" rel="noopener">17:00</a>))</li></ul></div></article><article class="it full" id="v-8QgBcI40VC8" data-title="The Best Agent IDE I&#39;ve ever used (Orca)" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=8QgBcI40VC8" target="_blank" rel="noopener"><img src="'+d+'" srcset="'+Q+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=8QgBcI40VC8" target="_blank" rel="noopener">The Best Agent IDE I&#39;ve ever used (Orca)</a></h3><div class="meta">Better Stack · Warren · uploaded 24 Oct, 2:30 AM IST · 7:05</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a short demo of a free tool; useful if you run several coding agents at once.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 13 times before (incl. BAND&#39;s &quot;you&#39;re the router between Claude and Codex&quot;). New here: a free desktop app that does that routing for you across worktrees.</div><div class="sh">What Orca is</div><ul><li><strong>Every agent in one window:</strong> Orca is a free, open-source app (100,000+ GitHub stars, he says) that runs Claude Code, Codex and other CLI agents side by side. He calls it the biggest change to his workflow from any tool he has reviewed ((<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=32s" target="_blank" rel="noopener">0:32</a>))</li><li><strong>Everything is a terminal:</strong> Each tab is a plain terminal running Claude Code, Codex, Goose, Kimi and others, with progress indicators and logos in the sidebar, plus a file viewer that renders markdown ((<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=38s" target="_blank" rel="noopener">0:38</a>–<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=97s" target="_blank" rel="noopener">1:37</a>))</li><li><strong>Worktrees and usage:</strong> &quot;+&quot; creates a git worktree on a new branch, starts your chosen agent in it and deletes the worktree when you&#39;re done. A footer shows weekly usage across Claude, Codex and Cursor ((<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=99s" target="_blank" rel="noopener">1:39</a>–<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=150s" target="_blank" rel="noopener">2:30</a>))</li></ul><div class="sh">Built-in tooling</div><ul><li><strong>Browser with annotations:</strong> Open localhost in a built-in browser, click a page element, write a comment and send it to an agent with the exact element target. In his demo, the title changed as asked ((<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=150s" target="_blank" rel="noopener">2:30</a>–<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=198s" target="_blank" rel="noopener">3:18</a>))</li><li><strong>Git and previews:</strong> Git changes and PR creation to GitHub, previews of images, videos, PDFs and markdown, and scheduled automations ((<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=198s" target="_blank" rel="noopener">3:18</a>–<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=224s" target="_blank" rel="noopener">3:44</a>))</li><li><strong>Orchestration:</strong> After you install a set of skills, Orca can split a task across agents, e.g. Claude on backend and Codex on frontend, or both on the same feature in separate worktrees for comparison. In his demo, one &quot;redesign with the Apple Design skill using Claude and Codex&quot; prompt opened a tab for each ((<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=224s" target="_blank" rel="noopener">3:44</a>–<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=318s" target="_blank" rel="noopener">5:18</a>))</li></ul><div class="sh">Switching</div><ul><li><strong>Over Herdr in Ghostty:</strong> Herdr misreported agents as finished while subagents or bash commands were still running, and its all-in-terminal UI felt cramped. There&#39;s also a mobile app for every provider, replacing separate Claude and ChatGPT apps ((<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=318s" target="_blank" rel="noopener">5:18</a>–<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=354s" target="_blank" rel="noopener">5:54</a>))</li><li><strong>Extras:</strong> Drag files into agents, annotate diffs and send comments back, the `orca` CLI, GitHub and Linear integration, and a keep-awake toggle that replaces caffeinate ((<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=371s" target="_blank" rel="noopener">6:11</a>–<a href="https://www.youtube.com/watch?v=8QgBcI40VC8&amp;t=409s" target="_blank" rel="noopener">6:49</a>))</li></ul></div></article><article class="it full" id="v-AhVHtwh5k3E" data-title="This Open-Source Tool Generates UI Like Magic" data-channel="Better Stack" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=AhVHtwh5k3E" target="_blank" rel="noopener"><img src="'+u+'" srcset="'+H+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=AhVHtwh5k3E" target="_blank" rel="noopener">This Open-Source Tool Generates UI Like Magic</a></h3><div class="meta">Better Stack · Warren · uploaded 23 Oct, 11:30 AM IST · 6:45</div><div class="verdict v-skim"><b>Verdict:</b> skim from 1:21 — a quick, new explainer of generative-UI specs; the token comparison with JSON Render and A2UI is the useful part.</div><div class="sh">The demo</div><ul><li><strong>An app launcher with no source code:</strong> Type a name like &quot;calculator&quot; or &quot;coffee shop finder&quot; and Gemini 3.8 Flash generates the app and its icon on demand, streamed in and working (20 + 5 works, the coffee finder loads Google Maps). Rendering uses OpenUI ((<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=86s" target="_blank" rel="noopener">1:26</a>))</li><li><strong>What it&#39;s for:</strong> Small on-demand UI for data or forms in chat. He links it to ChatGPT&#39;s new &quot;intelligent UI&quot;. OpenUI&#39;s own demos turn &quot;plan a day in San Francisco&quot; into a map, pills and an activity list, and build a playable drum pad ((<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=92s" target="_blank" rel="noopener">1:32</a>–<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=164s" target="_blank" rel="noopener">2:44</a>))</li></ul><div class="sh">How OpenUI works</div><ul><li><strong>A spec, not a library:</strong> It works with React, Vue or Svelte and shadcn/Tailwind, Chakra or Material. OpenUI&#39;s own component library is optional ((<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=164s" target="_blank" rel="noopener">2:44</a>–<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=186s" target="_blank" rel="noopener">3:06</a>))</li><li><strong>Why not JSON:</strong> Nested JSON can&#39;t be parsed until the whole response arrives. OpenUI Lang is a compact line-by-line format that renders as it streams and uses fewer tokens ((<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=186s" target="_blank" rel="noopener">3:06</a>–<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=223s" target="_blank" rel="noopener">3:43</a>))</li><li><strong>Wiring:</strong> `@openuidev/react-ui` supplies a system prompt describing your component list and OpenUI Lang, and `@openuidev/react-lang` turns the model&#39;s output into React components. Everything runs on your own server and client ((<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=223s" target="_blank" rel="noopener">3:43</a>–<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=253s" target="_blank" rel="noopener">4:13</a>))</li><li><strong>Vs. the alternatives:</strong> Vercel&#39;s JSON Render also streams line by line but uses 2×+ the tokens and 2×+ the latency. Google&#39;s A2UI (also supports Flutter) uses 2×+ the tokens ((<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=253s" target="_blank" rel="noopener">4:13</a>–<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=298s" target="_blank" rel="noopener">4:58</a>))</li></ul><div class="sh">Limits</div><ul><li><strong>Where it fits:</strong> Generative UI in chat, charts for viewing data, and richer input than the same radio-button card every time ((<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=319s" target="_blank" rel="noopener">5:19</a>))</li><li><strong>What broke:</strong> The demo isn&#39;t production-ready. Cerebras ran Qwen 3.8 at 1,800+ tokens/s, but it built broken apps and kept hitting rate limits, so he switched to Gemini. His vision: a secure backend in a user-scoped sandbox, with only the frontend generated ((<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=328s" target="_blank" rel="noopener">5:28</a>–<a href="https://www.youtube.com/watch?v=AhVHtwh5k3E&amp;t=386s" target="_blank" rel="noopener">6:26</a>))</li></ul></div></article></div>',1))])}const X=b(z,[["render",D]]);export{J as __pageData,X as default};
